{
  "name": "Measurement Registration Process",
  "resources": [
    {
      "name": "MSPN",
      "capacity": 1,
      "resource_type": "external_party"
    },
    {
      "name": "GO",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "MSPO",
      "capacity": 1,
      "resource_type": "external_party"
    },
    {
      "name": "MPO",
      "capacity": 1,
      "resource_type": "external_party"
    },
    {
      "name": "SP",
      "capacity": 1,
      "resource_type": "external_party"
    }
  ],
  "events": [
    {
      "id": "evt_start_mspn",
      "name": "Measurement Registration Needed",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_send_reg",
      "name": "Measurement Registration Sent",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Measurement Registration Application"
    },
    {
      "id": "evt_rec_reg",
      "name": "Measurement Registration Received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Measurement Registration Application"
    },
    {
      "id": "evt_end_rejected",
      "name": "Application Rejected",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_send_mspo",
      "name": "Inform MSPO Sent",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Assignment Notice MSPO"
    },
    {
      "id": "evt_send_mpo",
      "name": "Inform MPO Sent",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Assignment Notice MPO"
    },
    {
      "id": "evt_send_sp",
      "name": "Inform SP Sent",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Assignment Notice SP"
    },
    {
      "id": "evt_rec_mspo",
      "name": "Assignment Notice Received by MSPO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Assignment Notice MSPO"
    },
    {
      "id": "evt_end_mspo",
      "name": "MSPO Informed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_rec_mpo",
      "name": "Assignment Notice Received by MPO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Assignment Notice MPO"
    },
    {
      "id": "evt_end_mpo",
      "name": "MPO Informed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_rec_sp",
      "name": "Assignment Notice Received by SP",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Assignment Notice SP"
    },
    {
      "id": "evt_end_sp",
      "name": "SP Informed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_register",
      "name": "Register measurement at GO",
      "bpmn_type": "bpmn:Task",
      "resource_name": "MSPN",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["doc_application"]
    },
    {
      "id": "task_examine",
      "name": "Examine application of MSPN",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["doc_application"],
      "output_data_ids": []
    },
    {
      "id": "task_reject",
      "name": "Reject application of MSPN",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["doc_application"],
      "output_data_ids": []
    },
    {
      "id": "task_confirm",
      "name": "Confirm application of MSPN",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["doc_application"],
      "output_data_ids": []
    },
    {
      "id": "task_assign",
      "name": "Assign MSPN",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_inform_mspo",
      "name": "Inform MSPO about assignment",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_inform_mpo",
      "name": "Inform MPO about assignment",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_inform_sp",
      "name": "Inform SP about assignment",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    }
  ],
  "gateways": [
    {
      "id": "gw_decision",
      "name": "Application Status?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "seq_to_reject",
          "condition": "Rejected"
        },
        {
          "flow_id": "seq_to_confirm",
          "condition": "Confirmed"
        }
      ]
    }
  ],
  "sequence_flows": [
    {
      "id": "seq_mspn_1",
      "source_id": "evt_start_mspn",
      "target_id": "task_register"
    },
    {
      "id": "seq_mspn_2",
      "source_id": "task_register",
      "target_id": "evt_send_reg"
    },
    {
      "id": "seq_go_1",
      "source_id": "evt_rec_reg",
      "target_id": "task_examine"
    },
    {
      "id": "seq_go_2",
      "source_id": "task_examine",
      "target_id": "gw_decision"
    },
    {
      "id": "seq_to_reject",
      "source_id": "gw_decision",
      "target_id": "task_reject",
      "condition_name": "Rejected"
    },
    {
      "id": "seq_go_reject_end",
      "source_id": "task_reject",
      "target_id": "evt_end_rejected"
    },
    {
      "id": "seq_to_confirm",
      "source_id": "gw_decision",
      "target_id": "task_confirm",
      "condition_name": "Confirmed"
    },
    {
      "id": "seq_go_3",
      "source_id": "task_confirm",
      "target_id": "task_assign"
    },
    {
      "id": "seq_go_4",
      "source_id": "task_assign",
      "target_id": "task_inform_mspo"
    },
    {
      "id": "seq_go_5",
      "source_id": "task_inform_mspo",
      "target_id": "evt_send_mspo"
    },
    {
      "id": "seq_go_6",
      "source_id": "evt_send_mspo",
      "target_id": "task_inform_mpo"
    },
    {
      "id": "seq_go_7",
      "source_id": "task_inform_mpo",
      "target_id": "evt_send_mpo"
    },
    {
      "id": "seq_go_8",
      "source_id": "evt_send_mpo",
      "target_id": "task_inform_sp"
    },
    {
      "id": "seq_go_9",
      "source_id": "task_inform_sp",
      "target_id": "evt_send_sp"
    },
    {
      "id": "seq_mspo_1",
      "source_id": "evt_rec_mspo",
      "target_id": "evt_end_mspo"
    },
    {
      "id": "seq_mpo_1",
      "source_id": "evt_rec_mpo",
      "target_id": "evt_end_mpo"
    },
    {
      "id": "seq_sp_1",
      "source_id": "evt_rec_sp",
      "target_id": "evt_end_sp"
    }
  ],
  "pools": [
    {
      "id": "pool_mspn",
      "name": "MSPN",
      "element_ids": [
        "evt_start_mspn",
        "task_register",
        "evt_send_reg"
      ]
    },
    {
      "id": "pool_go",
      "name": "GO",
      "element_ids": [
        "evt_rec_reg",
        "task_examine",
        "gw_decision",
        "task_reject",
        "evt_end_rejected",
        "task_confirm",
        "task_assign",
        "task_inform_mspo",
        "evt_send_mspo",
        "task_inform_mpo",
        "evt_send_mpo",
        "task_inform_sp",
        "evt_send_sp"
      ]
    },
    {
      "id": "pool_mspo",
      "name": "MSPO",
      "element_ids": [
        "evt_rec_mspo",
        "evt_end_mspo"
      ]
    },
    {
      "id": "pool_mpo",
      "name": "MPO",
      "element_ids": [
        "evt_rec_mpo",
        "evt_end_mpo"
      ]
    },
    {
      "id": "pool_sp",
      "name": "SP",
      "element_ids": [
        "evt_rec_sp",
        "evt_end_sp"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_registration",
      "source_id": "evt_send_reg",
      "target_id": "evt_rec_reg",
      "name": "Measurement Registration Application"
    },
    {
      "id": "mf_inform_mspo",
      "source_id": "evt_send_mspo",
      "target_id": "evt_rec_mspo",
      "name": "Assignment Notice MSPO"
    },
    {
      "id": "mf_inform_mpo",
      "source_id": "evt_send_mpo",
      "target_id": "evt_rec_mpo",
      "name": "Assignment Notice MPO"
    },
    {
      "id": "mf_inform_sp",
      "source_id": "evt_send_sp",
      "target_id": "evt_rec_sp",
      "name": "Assignment Notice SP"
    }
  ],
  "data_objects": [
    {
      "id": "doc_application",
      "name": "Application of the MSPN"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
